CREATE TABLE app_private.sb_admin_users(user_id text PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now()); REVOKE ALL ON app_private.sb_admin_users FROM PUBLIC,anon,authenticated;
CREATE FUNCTION app_private.sb_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM app_private.sb_admin_users WHERE user_id=(SELECT auth.uid())::text) $$;
REVOKE ALL ON FUNCTION app_private.sb_is_admin() FROM PUBLIC; GRANT EXECUTE ON FUNCTION app_private.sb_is_admin() TO authenticated;
CREATE FUNCTION public.sb_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT app_private.sb_is_admin() $$;
REVOKE ALL ON FUNCTION public.sb_is_admin() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_is_admin() TO authenticated;
CREATE TABLE public.user_preferences(user_id varchar(36) PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,experience text NOT NULL DEFAULT 'beginner' CHECK(experience IN ('beginner','intermediate','advanced','professional')),markets jsonb NOT NULL DEFAULT '["KR","US"]',sectors jsonb NOT NULL DEFAULT '[]',alert_frequency text NOT NULL DEFAULT 'essential' CHECK(alert_frequency IN ('essential','normal','all')),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(jsonb_typeof(markets)='array' AND jsonb_array_length(markets)<=2),CHECK(jsonb_typeof(sectors)='array' AND jsonb_array_length(sectors)<=5));
CREATE TABLE public.question_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id varchar(36) NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,event_id varchar(36) NOT NULL REFERENCES public.events(id) ON DELETE RESTRICT,question text NOT NULL CHECK(length(question) BETWEEN 1 AND 2000),answer jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX ix_question_history_user_event ON public.question_history(user_id,event_id,created_at DESC);
CREATE TABLE app_private.calendar_subscriptions(user_id varchar(36) PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL DEFAULT now()+interval '90 days'); REVOKE ALL ON app_private.calendar_subscriptions FROM PUBLIC,anon,authenticated;
ALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY; ALTER TABLE public.question_history ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.user_preferences,public.question_history FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.user_preferences,public.question_history TO authenticated;
CREATE POLICY owner_select ON public.user_preferences FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid())::text); CREATE POLICY owner_select ON public.question_history FOR SELECT TO authenticated USING(user_id=(SELECT auth.uid())::text);
CREATE FUNCTION app_private.sb_event_visible(eid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ WITH RECURSIVE ancestors(id) AS (SELECT eid UNION SELECT f.event_id FROM ancestors a JOIN public.changes c ON c.event_id=a.id JOIN public.facts f ON f.id=c.previous_fact_id) SELECT EXISTS(SELECT 1 FROM public.events e JOIN public.documents d ON d.id=e.document_id WHERE e.id=eid AND e.state='published' AND e.published_to_users_at IS NOT NULL AND NOT d.is_demo) AND NOT EXISTS(SELECT 1 FROM ancestors a JOIN public.events e ON e.id=a.id WHERE e.state IN ('rejected','duplicate')) AND NOT EXISTS(SELECT 1 FROM public.facts f WHERE f.event_id=eid AND f.validation_status<>'supported') $$;
CREATE FUNCTION app_private.sb_fact_visible(fid text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.facts f WHERE f.id=fid AND f.validation_status='supported' AND (app_private.sb_event_visible(f.event_id) OR EXISTS(SELECT 1 FROM public.changes c WHERE c.previous_fact_id=f.id AND app_private.sb_event_visible(c.event_id)))) $$;
CREATE FUNCTION app_private.sb_document_visible(did text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.events e WHERE e.document_id=did AND app_private.sb_event_visible(e.id)) OR EXISTS(SELECT 1 FROM public.document_chunks c JOIN public.facts f ON f.chunk_id=c.id WHERE c.document_id=did AND app_private.sb_fact_visible(f.id)) $$;
REVOKE ALL ON FUNCTION app_private.sb_event_visible(text),app_private.sb_fact_visible(text),app_private.sb_document_visible(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION app_private.sb_event_visible(text),app_private.sb_fact_visible(text),app_private.sb_document_visible(text) TO authenticated;
GRANT SELECT ON public.companies,public.events,public.briefs,public.facts,public.changes,public.event_sources,public.brief_sources,public.document_chunks,public.validations,public.ai_runs TO authenticated;
GRANT SELECT(id,company_id,provider,external_id,title,form_type,source_url,published_at,publication_date,publication_precision,publication_timezone,ingested_at,raw_sha256,state,is_demo,created_at) ON public.documents TO authenticated;
CREATE POLICY catalog_read ON public.companies FOR SELECT TO authenticated USING(NOT is_demo OR app_private.sb_is_admin());
CREATE POLICY published_read ON public.events FOR SELECT TO authenticated USING(app_private.sb_event_visible(id)); CREATE POLICY published_read ON public.briefs FOR SELECT TO authenticated USING(app_private.sb_event_visible(event_id)); CREATE POLICY published_read ON public.facts FOR SELECT TO authenticated USING(app_private.sb_fact_visible(id)); CREATE POLICY published_read ON public.changes FOR SELECT TO authenticated USING(app_private.sb_event_visible(event_id)); CREATE POLICY published_read ON public.event_sources FOR SELECT TO authenticated USING(app_private.sb_event_visible(event_id));
CREATE POLICY published_read ON public.brief_sources FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.briefs b WHERE b.id=brief_id));
CREATE POLICY published_read ON public.document_chunks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.facts f WHERE f.chunk_id=document_chunks.id AND app_private.sb_fact_visible(f.id)));
CREATE POLICY published_read ON public.documents FOR SELECT TO authenticated USING(app_private.sb_document_visible(id)); CREATE POLICY published_read ON public.validations FOR SELECT TO authenticated USING(app_private.sb_event_visible(event_id));
CREATE POLICY published_read ON public.ai_runs FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.events e WHERE e.run_id=ai_runs.id AND app_private.sb_event_visible(e.id)));
CREATE POLICY official_read ON public.calendar_items FOR SELECT TO authenticated USING(origin='official' AND app_private.sb_event_visible(event_id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['users','companies','documents','document_chunks','events','briefs','facts','changes','validations','ai_runs','jobs','audit_logs','feedback','raw_blobs','eval_results','experiments','event_sources','brief_sources'] LOOP EXECUTE format('CREATE POLICY admin_read ON public.%I FOR SELECT TO authenticated USING((SELECT app_private.sb_is_admin()))',t); END LOOP; END $$;
GRANT SELECT ON public.jobs,public.audit_logs,public.feedback,public.raw_blobs,public.eval_results,public.experiments TO authenticated;
CREATE POLICY admin_raw_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='signalbrief-raw' AND (SELECT app_private.sb_is_admin()));
CREATE FUNCTION public.sb_initialize_profile() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;n text;result jsonb; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; SELECT left(coalesce(nullif(raw_user_meta_data->>'full_name',''),nullif(raw_user_meta_data->>'name',''),'Investor'),100) INTO n FROM auth.users WHERE id=u::uuid; IF n IS NULL THEN RAISE EXCEPTION 'identity_not_found' USING ERRCODE='PT401'; END IF; INSERT INTO public.users(id,display_name,density,onboarding_completed,analytics_consent,created_at,updated_at) VALUES(u,n,'beginner',false,false,now(),now()) ON CONFLICT(id) DO NOTHING; INSERT INTO public.watchlists(id,user_id,name,created_at) VALUES(gen_random_uuid()::text,u,'관심종목',now()) ON CONFLICT(user_id,name) DO NOTHING; INSERT INTO public.portfolios(id,user_id,name,created_at) VALUES(gen_random_uuid()::text,u,'내 포트폴리오',now()) ON CONFLICT(user_id,name) DO NOTHING; INSERT INTO public.user_preferences(user_id) VALUES(u) ON CONFLICT DO NOTHING; SELECT to_jsonb(p)||jsonb_build_object('is_admin',app_private.sb_is_admin(),'demo_mode',false) INTO result FROM public.users p WHERE p.id=u; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.sb_initialize_profile() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_initialize_profile() TO authenticated;
CREATE FUNCTION public.sb_rate_limit() RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE u text:=(SELECT auth.uid())::text;k text;h int; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='PT401'; END IF; k:='web:'||u||':'||floor(extract(epoch FROM now())/60)::text; INSERT INTO public.rate_buckets(key,hits,expires_at) VALUES(k,1,now()+interval '2 minutes') ON CONFLICT(key) DO UPDATE SET hits=public.rate_buckets.hits+1 RETURNING hits INTO h; IF h>120 THEN RAISE EXCEPTION 'rate_limit' USING ERRCODE='PT429'; END IF; DELETE FROM public.rate_buckets WHERE expires_at<now()-interval '1 hour'; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.sb_rate_limit() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_rate_limit() TO authenticated;
CREATE FUNCTION public.sb_portfolio() RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$ SELECT jsonb_build_object('id',p.id,'name',p.name,'weighting_note','Market prices are not connected. Quantities and cost basis are saved; no market value or FX rate is inferred.','positions',coalesce((SELECT jsonb_agg(jsonb_build_object('id',s.id,'company',to_jsonb(c),'quantity',s.quantity::text,'average_cost',s.average_cost::text,'currency',s.currency) ORDER BY c.name) FROM public.positions s JOIN public.companies c ON c.id=s.company_id WHERE s.portfolio_id=p.id),'[]'::jsonb)) FROM public.portfolios p WHERE p.user_id=(SELECT auth.uid())::text AND p.name='내 포트폴리오' $$;
REVOKE ALL ON FUNCTION public.sb_portfolio() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.sb_portfolio() TO authenticated; NOTIFY pgrst,'reload schema';